class Solution {
    private static final int INF = 1_000_000;

    public int findMinStep(String board, String hand) {
        int[] handCount = new int[26];
        for (char c : hand.toCharArray()) handCount[c - 'A']++;
        java.util.Map<String, Integer> memo = new java.util.HashMap<>();
        int answer = dfs(clean(board), handCount, memo);
        return answer >= INF ? -1 : answer;
    }

    private int dfs(String board, int[] hand, java.util.Map<String, Integer> memo) {
        board = clean(board);
        if (board.isEmpty()) return 0;
        String key = board + java.util.Arrays.toString(hand);
        if (memo.containsKey(key)) return memo.get(key);

        int best = INF;
        for (int i = 0; i < board.length();) {
            int j = i + 1;
            while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
            int need = 3 - (j - i);
            int color = board.charAt(i) - 'A';
            if (hand[color] >= need) {
                hand[color] -= need;
                String newBoard = clean(board.substring(0, i) + board.substring(j));
                int rest = dfs(newBoard, hand, memo);
                if (rest < INF) best = Math.min(best, need + rest);
                hand[color] += need;
            }
            i = j;
        }

        memo.put(key, best);
        return best;
    }

    private String clean(String board) {
        boolean changed = true;
        while (changed) {
            changed = false;
            StringBuilder next = new StringBuilder();
            for (int i = 0; i < board.length();) {
                int j = i + 1;
                while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
                if (j - i >= 3) changed = true;
                else next.append(board, i, j);
                i = j;
            }
            board = next.toString();
        }
        return board;
    }
}

