class Solution {
    public int findMinStep(String board, String hand) {
        char[] chars = hand.toCharArray();
        Arrays.sort(chars);
        String sortedHand = new String(chars);
        Queue<String[]> queue = new ArrayDeque<>();
        Set<String> visited = new HashSet<>();
        queue.offer(new String[]{clean(board), sortedHand});
        visited.add(clean(board) + "#" + sortedHand);

        int steps = 0;
        while (!queue.isEmpty()) {
            for (int size = queue.size(); size > 0; size--) {
                String[] state = queue.poll();
                String currentBoard = state[0];
                String currentHand = state[1];
                if (currentBoard.isEmpty()) return steps;
                for (int i = 0; i < currentHand.length(); i++) {
                    if (i > 0 && currentHand.charAt(i) == currentHand.charAt(i - 1)) continue;
                    char ball = currentHand.charAt(i);
                    String nextHand = currentHand.substring(0, i) + currentHand.substring(i + 1);
                    for (int pos = 0; pos <= currentBoard.length(); pos++) {
                        if (pos > 0 && currentBoard.charAt(pos - 1) == ball) continue;
                        String nextBoard = clean(currentBoard.substring(0, pos) + ball + currentBoard.substring(pos));
                        String key = nextBoard + "#" + nextHand;
                        if (visited.add(key)) queue.offer(new String[]{nextBoard, nextHand});
                    }
                }
            }
            steps++;
        }
        return -1;
    }

    private String clean(String board) {
        for (int i = 0; i < board.length();) {
            int j = i + 1;
            while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
            if (j - i >= 3) return clean(board.substring(0, i) + board.substring(j));
            i = j;
        }
        return board;
    }
}

