class Solution {
    public int findMinStep(String board, String hand) {
        int[] count = new int[26];
        for (char c : hand.toCharArray()) count[c - 'A']++;
        for (int limit = 0; limit <= hand.length(); limit++) {
            if (canClear(board, count, limit, new HashSet<>())) return limit;
        }
        return -1;
    }

    private boolean canClear(String board, int[] count, int remaining, Set<String> seen) {
        board = shrink(board);
        if (board.isEmpty()) return true;
        if (remaining == 0) return false;
        String key = board + "#" + remaining + "#" + Arrays.toString(count);
        if (!seen.add(key)) return false;

        for (int i = 0; i < board.length();) {
            int j = i + 1;
            while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
            int need = 3 - (j - i);
            int color = board.charAt(i) - 'A';
            if (need <= remaining && count[color] >= need) {
                count[color] -= need;
                String next = board.substring(0, i) + board.substring(j);
                if (canClear(next, count, remaining - need, seen)) {
                    count[color] += need;
                    return true;
                }
                count[color] += need;
            }
            i = j;
        }
        return false;
    }

    private String shrink(String board) {
        boolean changed = true;
        while (changed) {
            changed = false;
            StringBuilder next = new StringBuilder();
            for (int i = 0; i < board.length();) {
                int j = i + 1;
                while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
                if (j - i >= 3) changed = true;
                else next.append(board, i, j);
                i = j;
            }
            board = next.toString();
        }
        return board;
    }
}

