class Solution {
    private static final int INF = 1_000_000;

    public int findMinStep(String board, String hand) {
        char[] balls = hand.toCharArray();
        Arrays.sort(balls);
        int answer = dfs(clean(board), new String(balls), new HashMap<>());
        return answer >= INF ? -1 : answer;
    }

    private int dfs(String board, String hand, Map<String, Integer> memo) {
        board = clean(board);
        if (board.isEmpty()) return 0;
        if (hand.isEmpty()) return INF;
        String key = board + "#" + hand;
        if (memo.containsKey(key)) return memo.get(key);

        int best = INF;
        for (int i = 0; i < hand.length(); i++) {
            if (i > 0 && hand.charAt(i) == hand.charAt(i - 1)) continue;
            char ball = hand.charAt(i);
            String nextHand = hand.substring(0, i) + hand.substring(i + 1);
            for (int pos = 0; pos <= board.length(); pos++) {
                if (pos > 0 && board.charAt(pos - 1) == ball) continue;
                String nextBoard = clean(board.substring(0, pos) + ball + board.substring(pos));
                int rest = dfs(nextBoard, nextHand, memo);
                if (rest < INF) best = Math.min(best, 1 + rest);
            }
        }
        memo.put(key, best);
        return best;
    }

    private String clean(String board) {
        for (int i = 0; i < board.length();) {
            int j = i + 1;
            while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
            if (j - i >= 3) return clean(board.substring(0, i) + board.substring(j));
            i = j;
        }
        return board;
    }
}

