class Solution {
    public int findMinStep(String board, String hand) {
        char[] balls = hand.toCharArray();
        Arrays.sort(balls);
        String sortedHand = new String(balls);
        PriorityQueue<State> queue = new PriorityQueue<>(Comparator.comparingInt(state -> state.used));
        Map<String, Integer> bestCost = new HashMap<>();
        String startBoard = clean(board);
        String startKey = startBoard + "#" + sortedHand;
        queue.offer(new State(startBoard, sortedHand, 0));
        bestCost.put(startKey, 0);

        while (!queue.isEmpty()) {
            State state = queue.poll();
            String key = state.board + "#" + state.hand;
            if (state.used != bestCost.getOrDefault(key, Integer.MAX_VALUE)) continue;
            if (state.board.isEmpty()) return state.used;
            for (int i = 0; i < state.hand.length(); i++) {
                if (i > 0 && state.hand.charAt(i) == state.hand.charAt(i - 1)) continue;
                char ball = state.hand.charAt(i);
                String nextHand = state.hand.substring(0, i) + state.hand.substring(i + 1);
                for (int pos = 0; pos <= state.board.length(); pos++) {
                    if (pos > 0 && state.board.charAt(pos - 1) == ball) continue;
                    String nextBoard = clean(state.board.substring(0, pos) + ball + state.board.substring(pos));
                    int nextUsed = state.used + 1;
                    String nextKey = nextBoard + "#" + nextHand;
                    if (nextUsed < bestCost.getOrDefault(nextKey, Integer.MAX_VALUE)) {
                        bestCost.put(nextKey, nextUsed);
                        queue.offer(new State(nextBoard, nextHand, nextUsed));
                    }
                }
            }
        }
        return -1;
    }

    private String clean(String board) {
        for (int i = 0; i < board.length();) {
            int j = i + 1;
            while (j < board.length() && board.charAt(j) == board.charAt(i)) j++;
            if (j - i >= 3) return clean(board.substring(0, i) + board.substring(j));
            i = j;
        }
        return board;
    }

    private static class State {
        final String board;
        final String hand;
        final int used;

        State(String board, String hand, int used) {
            this.board = board;
            this.hand = hand;
            this.used = used;
        }
    }
}
